run('Alert creation and deduplication',function()use($alerts,$simple){$alerts->checkProduct($simple);$alerts->checkProduct($simple);check('One active low-stock alert after repeated checks',InventoryAlert::where('product_id',$simple->id)->where('status','active')->count()===1);check('Repeated alert does not resend notification',Mail::sent(App\Mail\InventoryAlertMail::class)->count()===1);$simple->update(['stock'=>0]);$alerts->checkProduct($simple);check('Out-of-stock transition resolves old low alert',InventoryAlert::where('product_id',$simple->id)->where('status','active')->where('alert_type','out_of_stock')->count()===1 && InventoryAlert::where('product_id',$simple->id)->where('alert_type','low_stock')->first()->status==='resolved');$simple->update(['stock'=>2]);$alerts->checkProduct($simple);});
