run('Receipt correction and returns',function()use($receiving,$po2,$line2,$simple){$receipt=PurchaseOrderReceipt::where('purchase_order_id',$po2->id)->first();$receiptItem=$receipt->items()->first();$before=$simple->fresh()->stock;$receiving->correct(req(['quantity'=>1,'reason'=>'Audit correction']),$po2,$receipt,$receiptItem);check('Correction reduces stock and received quantity',$simple->fresh()->stock===$before-1 && $line2->fresh()->quantity_received===3);check('Correction cannot exceed receipt quantity',validationBlocked(fn()=>$receiving->correct(req(['quantity'=>2,'reason'=>'Over correction']),$po2,$receipt,$receiptItem)));$before=$simple->fresh()->stock;$receiving->storeReturn(req(['reason_category'=>'damaged','reason'=>'Fixture damaged item','items'=>[['purchase_order_item_id'=>$line2->id,'quantity'=>1]]]),$po2);$return=SupplierReturn::where('purchase_order_id',$po2->id)->latest('id')->first();check('Supplier return reduces stock once',$simple->fresh()->stock===$before-1 && $return->status==='submitted');$receiving->cancelReturn(req(['cancellation_reason'=>'Fixture cancellation']),$po2,$return);check('Cancelling submitted return restores stock',$simple->fresh()->stock===$before);check('Repeated return cancellation is blocked',validationBlocked(fn()=>$receiving->cancelReturn(req(['cancellation_reason'=>'Repeat cancellation']),$po2,$return)));});
